import { createTheme } from "@mui/material/styles";

const lightTheme = createTheme({
  palette: {
    primary: {
      main: "#006060",
    },
    secondary: {
      main: "#ebcea0",
    },
    background: {
      default: "#f0f0d8",
    },
  },
  typography: {
    fontFamily: "Metrophonic, sans-serif",
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: "12px",
          textTransform: "none",
        },
      },
    },
  },
});

export default getTheme;
